import { act, cleanup, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import type { TerminalSession } from "../lib/types";
import { TerminalPane } from "./TerminalPane";

const manager = vi.hoisted(() => ({
  applySettings: vi.fn(),
  updateSession: vi.fn(),
  getOrCreate: vi.fn(),
  getInstance: vi.fn(),
}));

vi.mock("../lib/terminalHostManager", () => ({ terminalHostManager: manager }));
vi.mock("../lib/terminalSettings", () => ({
  useTerminalSettings: () => ({ settings: { fontSize: 13 } }),
}));

type ResizeRecord = {
  callback: ResizeObserverCallback;
  observe: ReturnType<typeof vi.fn>;
  disconnect: ReturnType<typeof vi.fn>;
};

const resizeRecords: ResizeRecord[] = [];

class TestResizeObserver {
  readonly observe = vi.fn();
  readonly unobserve = vi.fn();
  readonly disconnect = vi.fn();

  constructor(readonly callback: ResizeObserverCallback) {
    resizeRecords.push({ callback, observe: this.observe, disconnect: this.disconnect });
  }
}

function session(): TerminalSession {
  return {
    id: "session-new",
    cwd: "/repo/main",
    workspaceId: "ws-main",
    worktree: { wsId: "ws-main", slug: "main" },
    backendSessionId: "backend-new",
    lifecycle: "working",
  };
}

describe("TerminalPane mounted sizing", () => {
  beforeEach(() => {
    manager.applySettings.mockReset();
    manager.updateSession.mockReset();
    manager.getOrCreate.mockReset();
    manager.getInstance.mockReset();
    resizeRecords.length = 0;
    vi.stubGlobal("ResizeObserver", TestResizeObserver);
  });

  afterEach(() => {
    cleanup();
    vi.unstubAllGlobals();
  });

  it("waits for a measurable mounted container and then fits the new terminal to the full pane", async () => {
    const element = document.createElement("div");
    element.className = "terminal-host";
    const fit = vi.fn();
    const focus = vi.fn();
    const instance = {
      element,
      fitAddon: { fit },
      terminal: { focus },
      active: true,
      session: session(),
    };
    manager.getOrCreate.mockResolvedValue(instance);
    manager.getInstance.mockReturnValue(instance);

    render(<TerminalPane session={session()} active />);
    const mount = screen.getByTestId("terminal-mount");
    let width = 0;
    let height = 0;
    vi.spyOn(mount, "getBoundingClientRect").mockImplementation(
      () =>
        ({
          left: 0,
          top: 0,
          right: width,
          bottom: height,
          width,
          height,
          x: 0,
          y: 0,
          toJSON: () => ({}),
        }) as DOMRect,
    );

    await waitFor(() => expect(manager.getOrCreate).toHaveBeenCalledOnce());
    await waitFor(() => expect(resizeRecords).toHaveLength(1));
    expect(resizeRecords[0].observe).toHaveBeenCalledWith(mount);
    expect(element.parentElement).toBe(mount);
    expect(fit).not.toHaveBeenCalled();

    width = 960;
    height = 640;
    act(() => {
      resizeRecords[0].callback([], {} as ResizeObserver);
    });

    await waitFor(() => expect(fit).toHaveBeenCalled());
    expect(element.style.position).toBe("absolute");
    expect(element.style.inset).toBe("0px");
    expect(element.style.width).toBe("100%");
    expect(element.style.height).toBe("100%");
    expect(element.style.minWidth).toBe("0px");
    expect(element.style.minHeight).toBe("0px");
  });
});

import { act, cleanup, renderHook } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { TerminalSession, TerminalTab, Worktree } from "../lib/types";
import type { PaneNode } from "./paneTree";
import { useWorkspaceStore, type WorkspaceServices, type WorkspaceState } from "./workspaceStore";

afterEach(cleanup);

const targetWorktree: Worktree = {
  path: "/repo/target",
  head: "target-head",
  branch: "refs/heads/orca/ws-main/target",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

const sourceWorktree: Worktree = {
  ...targetWorktree,
  path: "/repo/source",
  head: "source-head",
  branch: "refs/heads/orca/ws-main/source",
};

function session(id: string, cwd: string, slug: string): TerminalSession {
  return {
    id,
    cwd,
    workspaceId: "ws-main",
    worktree: { wsId: "ws-main", slug },
    backendSessionId: `backend-${id}`,
    lifecycle: "working",
  };
}

function services(): WorkspaceServices {
  return {
    ensureTerminalEvents: vi.fn(async () => undefined),
    spawnTerminal: vi.fn(async () => "unexpected-backend"),
    closeTerminal: vi.fn(async () => undefined),
    waitForTerminalExit: vi.fn(async () => undefined),
  };
}

function restoredState(activeTabId = "tab-target"): WorkspaceState {
  const targetTab: TerminalTab = { id: "tab-target", label: "target", sessionId: "session-target" };
  const sourceTab: TerminalTab = { id: "tab-source", label: "source", sessionId: "session-source-primary" };
  return {
    worktrees: [targetWorktree, sourceWorktree],
    activeWorktreePath: targetWorktree.path,
    sessions: {
      "session-target": session("session-target", targetWorktree.path, "target"),
      "session-source-primary": session("session-source-primary", sourceWorktree.path, "source"),
      "session-source-active": session("session-source-active", sourceWorktree.path, "source"),
    },
    layout: {
      tabs: [targetTab, sourceTab],
      activeTabId,
      layoutsByTabId: {
        [targetTab.id]: {
          root: { type: "leaf", leafId: "leaf-target" },
          activeLeafId: "leaf-target",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-target": "session-target" },
        },
        [sourceTab.id]: {
          root: {
            type: "split",
            direction: "vertical",
            first: { type: "leaf", leafId: "leaf-source-primary" },
            second: { type: "leaf", leafId: "leaf-source-active" },
            ratio: 0.5,
          },
          activeLeafId: "leaf-source-active",
          expandedLeafId: null,
          sessionIdsByLeafId: {
            "leaf-source-primary": "session-source-primary",
            "leaf-source-active": "session-source-active",
          },
        },
      },
    },
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

function leafIds(node: PaneNode): string[] {
  if (node.type === "leaf") return [node.leafId];
  return [...leafIds(node.first), ...leafIds(node.second)];
}

function expectAllSessionsPreserved(state: WorkspaceState) {
  expect(state.sessions["session-target"]).toBeDefined();
  expect(state.sessions["session-source-primary"]).toBeDefined();
  expect(state.sessions["session-source-active"]).toBeDefined();
}

describe("useWorkspaceStore tab-to-pane split", () => {
  it("moves the dragged tab's entire pane subtree into the requested split without spawning or closing PTYs", async () => {
    const workspaceServices = services();
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );

    act(() => result.current.restoreWorkspace(restoredState()));
    await act(async () => {
      await result.current.splitPane("tab-target", "leaf-target", "horizontal", {
        sourceTabId: "tab-source",
        position: "first",
      });
    });

    expect(result.current.state.layout.tabs.map((tab) => tab.id)).toEqual(["tab-target"]);
    expect(result.current.state.layout.layoutsByTabId["tab-source"]).toBeUndefined();

    const targetLayout = result.current.state.layout.layoutsByTabId["tab-target"];
    expect(targetLayout.root.type).toBe("split");
    if (targetLayout.root.type !== "split") throw new Error("target pane was not split");

    expect(targetLayout.root.direction).toBe("horizontal");
    expect(targetLayout.root.first.type).toBe("split");
    expect(targetLayout.root.second).toEqual({ type: "leaf", leafId: "leaf-target" });
    if (targetLayout.root.first.type !== "split") throw new Error("source subtree was not moved intact");
    expect(targetLayout.root.first.direction).toBe("vertical");

    const movedSourceLeafIds = leafIds(targetLayout.root.first);
    expect(movedSourceLeafIds).toHaveLength(2);
    expect(movedSourceLeafIds).not.toContain("leaf-source-primary");
    expect(movedSourceLeafIds).not.toContain("leaf-source-active");
    expect(new Set(movedSourceLeafIds.map((leafId) => targetLayout.sessionIdsByLeafId[leafId]))).toEqual(
      new Set(["session-source-primary", "session-source-active"]),
    );
    expect(targetLayout.sessionIdsByLeafId["leaf-target"]).toBe("session-target");
    expect(targetLayout.sessionIdsByLeafId[targetLayout.activeLeafId!]).toBe("session-source-active");

    expectAllSessionsPreserved(result.current.state);
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });

  it("moves an already-split active tab as a whole when it is dragged onto its own edge and another tab exists", async () => {
    const workspaceServices = services();
    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree, sourceWorktree], services: workspaceServices }),
    );

    act(() => result.current.restoreWorkspace(restoredState("tab-source")));
    await act(async () => {
      await result.current.splitPane("tab-source", "leaf-source-active", "horizontal", {
        sourceTabId: "tab-source",
        position: "second",
      });
    });

    expect(result.current.state.layout.tabs.map((tab) => tab.id)).toEqual(["tab-target"]);
    expect(result.current.state.layout.activeTabId).toBe("tab-target");
    expect(result.current.state.layout.layoutsByTabId["tab-source"]).toBeUndefined();

    const targetLayout = result.current.state.layout.layoutsByTabId["tab-target"];
    expect(targetLayout.root.type).toBe("split");
    if (targetLayout.root.type !== "split") throw new Error("self-dropped source tab was not moved into a split");
    expect(targetLayout.root.direction).toBe("horizontal");
    expect(targetLayout.root.first).toEqual({ type: "leaf", leafId: "leaf-target" });
    expect(targetLayout.root.second.type).toBe("split");
    if (targetLayout.root.second.type !== "split") throw new Error("source subtree was not preserved on self-drop");
    expect(targetLayout.root.second.direction).toBe("vertical");

    const movedSourceLeafIds = leafIds(targetLayout.root.second);
    expect(new Set(movedSourceLeafIds.map((leafId) => targetLayout.sessionIdsByLeafId[leafId]))).toEqual(
      new Set(["session-source-primary", "session-source-active"]),
    );
    expect(targetLayout.sessionIdsByLeafId[targetLayout.activeLeafId!]).toBe("session-source-active");

    expectAllSessionsPreserved(result.current.state);
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });
});

import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { LayoutState, TerminalSession, TerminalTab } from "../lib/types";
import { TerminalSplitView } from "./TerminalSplitView";

vi.mock("./TerminalPane", () => ({
  TerminalPane: ({ session }: { session: TerminalSession }) => (
    <div data-testid="terminal-pane" data-session-id={session.id} />
  ),
}));

afterEach(cleanup);

function tab(id: string, sessionId: string): TerminalTab {
  return { id, label: id, sessionId };
}

function session(id: string): TerminalSession {
  return {
    id,
    cwd: "/repo",
    workspaceId: "ws-main",
    worktree: { wsId: "ws-main", slug: "main" },
    backendSessionId: `backend-${id}`,
    lifecycle: "working",
  };
}

function twoTabLayout(): LayoutState {
  return {
    tabs: [tab("tab-1", "session-1"), tab("tab-2", "session-2")],
    activeTabId: "tab-1",
    layoutsByTabId: {
      "tab-1": {
        root: { type: "leaf", leafId: "leaf-1" },
        activeLeafId: "leaf-1",
        expandedLeafId: null,
        sessionIdsByLeafId: { "leaf-1": "session-1" },
      },
      "tab-2": {
        root: { type: "leaf", leafId: "leaf-2" },
        activeLeafId: "leaf-2",
        expandedLeafId: null,
        sessionIdsByLeafId: { "leaf-2": "session-2" },
      },
    },
  };
}

function mockPaneRect(pane: HTMLElement) {
  return vi.spyOn(pane, "getBoundingClientRect").mockReturnValue({
    left: 0,
    right: 200,
    width: 200,
    top: 32,
    bottom: 132,
    height: 100,
    x: 0,
    y: 32,
    toJSON: () => ({}),
  });
}

function getTabElement(label: string) {
  return screen.getByText(label).closest('[role="tab"]') as HTMLElement;
}

function pointerDrag(tabElement: HTMLElement, pointerId: number, x: number, y: number) {
  fireEvent.pointerDown(tabElement, {
    button: 0,
    pointerId,
    isPrimary: true,
    clientX: 120,
    clientY: 16,
  });
  fireEvent.pointerMove(window, { pointerId, isPrimary: true, clientX: x, clientY: y });
}

describe("TerminalSplitView pointer tab drag", () => {
  it("routes another tab to all four Orca edge zones without relying on HTML5 DragEvent", () => {
    const onSplitPane = vi.fn();
    render(
      <TerminalSplitView
        layout={twoTabLayout()}
        sessions={{ "session-1": session("session-1"), "session-2": session("session-2") }}
        onSplitPane={onSplitPane}
        onReorderTab={vi.fn()}
      />,
    );

    const pane = screen.getByTestId("pane-leaf");
    mockPaneRect(pane);
    const sourceTab = getTabElement("tab-2");
    expect(sourceTab).toHaveAttribute("draggable", "false");
    const cases = [
      { point: [5, 82], edge: "left", direction: "horizontal", position: "first" },
      { point: [195, 82], edge: "right", direction: "horizontal", position: "second" },
      { point: [100, 37], edge: "top", direction: "vertical", position: "first" },
      { point: [100, 127], edge: "bottom", direction: "vertical", position: "second" },
    ] as const;

    cases.forEach(({ point, edge, direction, position }, index) => {
      pointerDrag(sourceTab, index + 1, point[0], point[1]);
      expect(screen.getByTestId("pane-drop-preview")).toHaveAttribute("data-drop-edge", edge);
      fireEvent.pointerUp(window, {
        pointerId: index + 1,
        isPrimary: true,
        clientX: point[0],
        clientY: point[1],
      });
      expect(onSplitPane).toHaveBeenLastCalledWith("tab-1", "leaf-1", direction, {
        sourceTabId: "tab-2",
        position,
      });
      expect(screen.queryByTestId("pane-drop-preview")).not.toBeInTheDocument();
    });

    expect(onSplitPane).toHaveBeenCalledTimes(4);
  });

  it("allows the active tab itself to use the pointer split path when another terminal tab exists", () => {
    const onSplitPane = vi.fn();
    render(
      <TerminalSplitView
        layout={twoTabLayout()}
        sessions={{ "session-1": session("session-1"), "session-2": session("session-2") }}
        onSplitPane={onSplitPane}
        onReorderTab={vi.fn()}
      />,
    );

    const pane = screen.getByTestId("pane-leaf");
    mockPaneRect(pane);
    const activeTab = getTabElement("tab-1");
    expect(activeTab).toHaveAttribute("draggable", "false");

    pointerDrag(activeTab, 11, 5, 82);
    expect(screen.getByTestId("pane-drop-preview")).toHaveAttribute("data-drop-edge", "left");
    fireEvent.pointerUp(window, { pointerId: 11, isPrimary: true, clientX: 5, clientY: 82 });

    expect(onSplitPane).toHaveBeenCalledWith("tab-1", "leaf-1", "horizontal", {
      sourceTabId: "tab-1",
      position: "first",
    });
  });
});

import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { LayoutState, TerminalSession, TerminalTab } from "../lib/types";
import { TerminalSplitView } from "./TerminalSplitView";

vi.mock("./TerminalPane", () => ({
  TerminalPane: ({ session }: { session: TerminalSession }) => (
    <div data-testid="terminal-pane" data-session-id={session.id} />
  ),
}));

afterEach(cleanup);

function tab(id: string, sessionId: string): TerminalTab {
  return { id, label: id, sessionId };
}

function session(id: string): TerminalSession {
  return {
    id,
    cwd: "/repo",
    workspaceId: "ws-main",
    worktree: { wsId: "ws-main", slug: "main" },
    backendSessionId: `backend-${id}`,
    lifecycle: "working",
  };
}

function plainTextOnlyTransfer(tabId: string) {
  return {
    setData: vi.fn(),
    getData: vi.fn((type: string) => (type === "text/plain" ? tabId : "")),
    get types() {
      return ["text/plain"];
    },
    effectAllowed: "move",
    dropEffect: "",
  };
}

describe("TerminalSplitView tab drop MIME fallback", () => {
  it("accepts a tab drop when WebKit exposes only text/plain and preserves the requested edge", () => {
    const layout: LayoutState = {
      tabs: [tab("tab-target", "session-target"), tab("tab-source", "session-source")],
      activeTabId: "tab-target",
      layoutsByTabId: {
        "tab-target": {
          root: { type: "leaf", leafId: "leaf-target" },
          activeLeafId: "leaf-target",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-target": "session-target" },
        },
        "tab-source": {
          root: { type: "leaf", leafId: "leaf-source" },
          activeLeafId: "leaf-source",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-source": "session-source" },
        },
      },
    };
    const onSplitPane = vi.fn();
    render(
      <TerminalSplitView
        layout={layout}
        sessions={{
          "session-target": session("session-target"),
          "session-source": session("session-source"),
        }}
        onSplitPane={onSplitPane}
        onReorderTab={vi.fn()}
      />,
    );

    const pane = screen.getByTestId("pane-leaf");
    vi.spyOn(pane, "getBoundingClientRect").mockReturnValue({
      left: 0,
      right: 200,
      width: 200,
      top: 0,
      bottom: 100,
      height: 100,
      x: 0,
      y: 0,
      toJSON: () => ({}),
    });

    const transfer = plainTextOnlyTransfer("tab-source");
    fireEvent.dragOver(pane, { clientX: 195, clientY: 50, dataTransfer: transfer });
    expect(screen.getByTestId("pane-drop-preview")).toHaveAttribute("data-drop-edge", "right");

    fireEvent.drop(pane, { clientX: 195, clientY: 50, dataTransfer: transfer });
    expect(onSplitPane).toHaveBeenCalledWith("tab-target", "leaf-target", "horizontal", {
      sourceTabId: "tab-source",
      position: "second",
    });
  });
});

import { Columns2, Rows2, X } from "lucide-react";
import React, { useRef, useState } from "react";

import type { ActivitySummary } from "../lib/activity";
import type { LayoutState, TabPaneLayout, TerminalSession, WorkspaceTab } from "../lib/types";
import type { PaneDirection, PaneNode } from "../state/paneTree";
import { BrowserPane } from "./BrowserPane";
import { TAB_DRAG_MIME, TabBar, type TabPointerDragPoint } from "./TabBar";
import { TerminalPane } from "./TerminalPane";
import { IconButton } from "./ui/IconButton";

const PANE_DRAG_MIME = "application/x-orca-pane";
type PaneDropEdge = "left" | "right" | "top" | "bottom";

type DraggedPane = { tabId: string; leafId: string };
type TabPointerDropTarget = { leafId: string; edge: PaneDropEdge };
type SplitPaneOptions = { sourceTabId?: string; position?: "first" | "second" };

type TerminalSplitViewProps = {
  layout: LayoutState;
  sessions: Record<string, TerminalSession>;
  onActivateTab?: (tabId: string) => void;
  onCloseTab?: (tabId: string) => void;
  onCloseOtherTabs?: (tabId: string) => void;
  onCloseTabsToRight?: (tabId: string) => void;
  onCloseTabsToLeft?: (tabId: string) => void;
  onReorderTab?: (tabId: string, targetIndex: number) => void;
  onRenameTab?: (tabId: string, label: string) => void;
  onToggleTabPin?: (tabId: string, pinned: boolean) => void;
  onAddTab?: () => void;
  onAddBrowserTab?: (url?: string) => void;
  onNavigateBrowserTab?: (tabId: string, url: string) => void;
  onReloadBrowserTab?: (tabId: string) => void;
  onSplitPane?: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onClosePane?: (tabId: string, leafId: string) => void;
  onSetRatio?: (tabId: string, path: string, ratio: number) => void;
  onSwapPanes?: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane?: (tabId: string, leafId: string) => void;
  onTitleChange?: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
  unreadTabIds?: Record<string, boolean>;
  activityByTabId?: Record<string, ActivitySummary | undefined>;
  leadingSpacer?: number;
};

export function TerminalSplitView({
  layout,
  sessions,
  onActivateTab = () => undefined,
  onCloseTab = () => undefined,
  onCloseOtherTabs,
  onCloseTabsToRight,
  onCloseTabsToLeft,
  onReorderTab,
  onRenameTab,
  onToggleTabPin,
  onAddTab = () => undefined,
  onAddBrowserTab = () => undefined,
  onNavigateBrowserTab = () => undefined,
  onReloadBrowserTab = () => undefined,
  onSplitPane = () => undefined,
  onClosePane = () => undefined,
  onSetRatio = () => undefined,
  onSwapPanes = () => undefined,
  onFocusPane = () => undefined,
  onTitleChange = () => undefined,
  onBell,
  unreadTabIds,
  activityByTabId,
  leadingSpacer = 0,
}: TerminalSplitViewProps) {
  const [draggedLeafId, setDraggedLeafId] = useState<DraggedPane | null>(null);
  const [tabPointerDragId, setTabPointerDragId] = useState<string | null>(null);
  const [tabPointerDropTarget, setTabPointerDropTarget] = useState<TabPointerDropTarget | null>(null);
  const terminalSurfaceRef = useRef<HTMLDivElement>(null);

  const activeTab = layout.tabs.find((tab) => tab.id === layout.activeTabId) ?? layout.tabs[0] ?? null;
  const activeTabLayout = activeTab ? getTabPaneLayout(layout, activeTab) : null;
  const isBrowserTab = activeTab?.kind === "browser";
  const terminalTabCount = layout.tabs.filter((candidate) => candidate.kind !== "browser").length;

  const splitTab = (tabId: string, direction: PaneDirection) => {
    const tab = layout.tabs.find((candidate) => candidate.id === tabId);
    if (!tab || tab.kind === "browser") return;
    const tabLayout = getTabPaneLayout(layout, tab);
    const targetLeafId = tabLayout.activeLeafId ?? firstLeafId(tabLayout.root);
    if (targetLeafId) onSplitPane(tab.id, targetLeafId, direction);
  };

  const resolveTabPointerDropTarget = (tabId: string, point: TabPointerDragPoint): TabPointerDropTarget | null => {
    if (!activeTab || activeTab.kind === "browser") return null;
    if (tabId === activeTab.id && terminalTabCount <= 1) return null;
    const surface = terminalSurfaceRef.current;
    if (!surface) return null;

    const panes = Array.from(surface.querySelectorAll<HTMLElement>('[data-testid="pane-leaf"]'));
    for (const pane of panes) {
      const rect = pane.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) continue;
      if (point.x < rect.left || point.x > rect.right || point.y < rect.top || point.y > rect.bottom) continue;
      const edge = resolvePaneDropEdgeFromRect(rect, point);
      if (!edge) return null;
      const leafId = pane.dataset.leafId;
      return leafId ? { leafId, edge } : null;
    }
    return null;
  };

  const updateTabPointerDropTarget = (tabId: string, point: TabPointerDragPoint) => {
    const next = resolveTabPointerDropTarget(tabId, point);
    setTabPointerDropTarget((current) =>
      current?.leafId === next?.leafId && current?.edge === next?.edge ? current : next,
    );
    return next;
  };

  const clearTabPointerDrag = () => {
    setTabPointerDragId(null);
    setTabPointerDropTarget(null);
  };

  const handleTabPointerDragStart = (tabId: string, point: TabPointerDragPoint) => {
    setTabPointerDragId(tabId);
    updateTabPointerDropTarget(tabId, point);
  };

  const handleTabPointerDragMove = (tabId: string, point: TabPointerDragPoint) => {
    updateTabPointerDropTarget(tabId, point);
  };

  const handleTabPointerDragEnd = (tabId: string, point: TabPointerDragPoint) => {
    const target = resolveTabPointerDropTarget(tabId, point) ?? tabPointerDropTarget;
    if (target && activeTab && activeTab.kind !== "browser") {
      const splitDirection: PaneDirection =
        target.edge === "top" || target.edge === "bottom" ? "vertical" : "horizontal";
      const position = target.edge === "left" || target.edge === "top" ? "first" : "second";
      onSplitPane(activeTab.id, target.leafId, splitDirection, { sourceTabId: tabId, position });
    }
    clearTabPointerDrag();
  };

  return (
    <div className="relative flex flex-1 flex-col overflow-hidden bg-terminal" data-testid="terminal-layout">
      <TabBar
        tabs={layout.tabs}
        activeTabId={activeTab?.id ?? ""}
        unreadTabIds={unreadTabIds}
        activityByTabId={activityByTabId}
        onActivate={onActivateTab}
        onClose={onCloseTab}
        onCloseOthers={onCloseOtherTabs}
        onCloseToRight={onCloseTabsToRight}
        onCloseToLeft={onCloseTabsToLeft}
        onReorderTabs={onReorderTab}
        onTabPointerDragStart={handleTabPointerDragStart}
        onTabPointerDragMove={handleTabPointerDragMove}
        onTabPointerDragEnd={handleTabPointerDragEnd}
        onTabPointerDragCancel={clearTabPointerDrag}
        onRenameTab={onRenameTab}
        onTogglePin={onToggleTabPin}
        onSplitRight={(tabId) => splitTab(tabId, "horizontal")}
        onSplitDown={(tabId) => splitTab(tabId, "vertical")}
        onAdd={onAddTab}
        onAddBrowser={onAddBrowserTab}
        leadingSpacer={leadingSpacer}
      />

      <div ref={terminalSurfaceRef} className="relative min-h-0 flex-1 overflow-hidden bg-terminal">
        {!activeTab ? null : isBrowserTab ? (
          <BrowserPane
            tab={activeTab}
            visible={true}
            onNavigate={(url) => onNavigateBrowserTab(activeTab.id, url)}
            onReload={() => onReloadBrowserTab(activeTab.id)}
          />
        ) : activeTabLayout ? (
          <PaneRenderer
            node={activeTabLayout.root}
            tab={activeTab}
            tabLayout={activeTabLayout}
            sessions={sessions}
            terminalTabCount={terminalTabCount}
            tabPointerDropTarget={tabPointerDragId ? tabPointerDropTarget : null}
            path=""
            draggedLeafId={draggedLeafId}
            setDraggedLeafId={setDraggedLeafId}
            onSplitPane={onSplitPane}
            onClosePane={onClosePane}
            onSetRatio={onSetRatio}
            onSwapPanes={onSwapPanes}
            onFocusPane={onFocusPane}
            onTitleChange={onTitleChange}
            onBell={onBell}
          />
        ) : null}
      </div>
    </div>
  );
}

function getTabPaneLayout(layout: LayoutState, tab: WorkspaceTab): TabPaneLayout {
  const isBrowserTab = tab.kind === "browser";
  return layout.layoutsByTabId?.[tab.id] ?? {
    root: { type: "leaf", leafId: "leaf-default" },
    activeLeafId: "leaf-default",
    expandedLeafId: null,
    sessionIdsByLeafId: { "leaf-default": isBrowserTab ? "" : tab.sessionId },
  };
}

function firstLeafId(node: PaneNode): string {
  let current = node;
  while (current.type === "split") current = current.first;
  return current.leafId;
}

function resolvePaneDropEdgeFromRect(
  rect: Pick<DOMRect, "left" | "top" | "width" | "height">,
  point: TabPointerDragPoint,
): PaneDropEdge | null {
  if (rect.width <= 0 || rect.height <= 0) return null;

  const localX = point.x - rect.left;
  const localY = point.y - rect.top;
  const horizontalEdge = rect.width * 0.2;
  const verticalEdge = rect.height * 0.2;

  if (localX < horizontalEdge) return "left";
  if (localX > rect.width - horizontalEdge) return "right";
  if (localY < verticalEdge) return "top";
  if (localY > rect.height - verticalEdge) return "bottom";
  return null;
}

function resolvePaneDropEdge(event: React.DragEvent): PaneDropEdge | null {
  return resolvePaneDropEdgeFromRect(event.currentTarget.getBoundingClientRect(), {
    x: event.clientX,
    y: event.clientY,
  });
}

function parseDraggedPane(value: string): DraggedPane | null {
  if (!value) return null;
  try {
    const parsed = JSON.parse(value) as Partial<DraggedPane>;
    if (typeof parsed.tabId === "string" && typeof parsed.leafId === "string") {
      return { tabId: parsed.tabId, leafId: parsed.leafId };
    }
  } catch {
    const separator = value.indexOf(":");
    if (separator > 0 && separator < value.length - 1) {
      return { tabId: value.slice(0, separator), leafId: value.slice(separator + 1) };
    }
  }
  return null;
}

type PaneRendererProps = {
  node: PaneNode;
  tab: WorkspaceTab;
  tabLayout: TabPaneLayout;
  sessions: Record<string, TerminalSession>;
  terminalTabCount: number;
  tabPointerDropTarget: TabPointerDropTarget | null;
  path: string;
  draggedLeafId: DraggedPane | null;
  setDraggedLeafId: (value: DraggedPane | null) => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onSetRatio: (tabId: string, path: string, ratio: number) => void;
  onSwapPanes: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
};

function PaneRenderer(props: PaneRendererProps) {
  const { node, tab, tabLayout, sessions, path } = props;

  if (node.type === "leaf") {
    const defaultSessionId = tab.kind === "browser" ? "" : tab.sessionId;
    const sessionId = tabLayout.sessionIdsByLeafId[node.leafId] ?? defaultSessionId;
    const session = sessions[sessionId] ?? {
      id: sessionId,
      cwd: "",
      workspaceId: "",
      worktree: null,
      backendSessionId: null,
      lifecycle: "working" as const,
    };
    const isOnlyLeaf = tabLayout.root.type === "leaf";

    return (
      <PaneLeafView
        leafId={node.leafId}
        tab={tab}
        session={session}
        isOnlyLeaf={isOnlyLeaf}
        isActive={tabLayout.activeLeafId === node.leafId}
        terminalTabCount={props.terminalTabCount}
        tabDropEdge={props.tabPointerDropTarget?.leafId === node.leafId ? props.tabPointerDropTarget.edge : null}
        draggedLeafId={props.draggedLeafId}
        setDraggedLeafId={props.setDraggedLeafId}
        onSplitPane={props.onSplitPane}
        onClosePane={props.onClosePane}
        onSwapPanes={props.onSwapPanes}
        onFocusPane={props.onFocusPane}
        onTitleChange={props.onTitleChange}
        onBell={props.onBell}
      />
    );
  }

  const isHorizontal = node.direction === "horizontal";
  const ratio = node.ratio ?? 0.5;

  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden ${isHorizontal ? "flex-row" : "flex-col"}`}
      data-testid="pane-split"
      data-direction={node.direction}
    >
      <div
        className="relative min-h-0 min-w-0 overflow-hidden"
        style={{ flexBasis: `${ratio * 100}%`, flexGrow: 0, flexShrink: 0 }}
      >
        <PaneRenderer {...props} node={node.first} path={path ? `${path}.first` : "first"} />
      </div>

      <PaneResizeDivider
        direction={node.direction}
        ratio={ratio}
        onRatioChange={(newRatio) => props.onSetRatio(tab.id, path, newRatio)}
      />

      <div
        className="relative min-h-0 min-w-0 flex-1 overflow-hidden"
        style={{ flexBasis: `${(1 - ratio) * 100}%`, flexGrow: 1, flexShrink: 1 }}
      >
        <PaneRenderer {...props} node={node.second} path={path ? `${path}.second` : "second"} />
      </div>
    </div>
  );
}

type PaneLeafViewProps = {
  leafId: string;
  tab: WorkspaceTab;
  session: TerminalSession;
  isOnlyLeaf: boolean;
  isActive: boolean;
  terminalTabCount: number;
  tabDropEdge: PaneDropEdge | null;
  draggedLeafId: DraggedPane | null;
  setDraggedLeafId: (value: DraggedPane | null) => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onSwapPanes: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
};

function PaneLeafView({
  leafId,
  tab,
  session,
  isOnlyLeaf,
  isActive,
  terminalTabCount,
  tabDropEdge,
  draggedLeafId,
  setDraggedLeafId,
  onSplitPane,
  onClosePane,
  onSwapPanes,
  onFocusPane,
  onTitleChange,
  onBell,
}: PaneLeafViewProps) {
  const [isDragOver, setIsDragOver] = useState(false);
  const [isHoveredTop, setIsHoveredTop] = useState(false);
  const [dropIndicator, setDropIndicator] = useState<PaneDropEdge | null>(null);
  const effectiveDropIndicator = tabDropEdge ?? dropIndicator;

  const handleDragStart = (event: React.DragEvent) => {
    if (event.target instanceof Element && event.target.closest("button")) {
      event.preventDefault();
      return;
    }
    const draggedPane = { tabId: tab.id, leafId };
    event.dataTransfer.setData("text/plain", `${tab.id}:${leafId}`);
    event.dataTransfer.setData(PANE_DRAG_MIME, JSON.stringify(draggedPane));
    event.dataTransfer.effectAllowed = "move";
    setDraggedLeafId(draggedPane);
  };

  const handleDragEnd = () => {
    setDraggedLeafId(null);
    setIsDragOver(false);
    setDropIndicator(null);
  };

  const handleDragOver = (event: React.DragEvent) => {
    const types = event.dataTransfer?.types ? Array.from(event.dataTransfer.types) : [];
    const isPaneDrag = Boolean(
      (draggedLeafId && draggedLeafId.tabId === tab.id && draggedLeafId.leafId !== leafId) ||
        types.includes(PANE_DRAG_MIME),
    );
    const isTabDrag = types.includes(TAB_DRAG_MIME) || (!isPaneDrag && types.includes("text/plain"));

    if (!isTabDrag && !isPaneDrag) return;

    if (isTabDrag) {
      const draggedTabId = event.dataTransfer.getData(TAB_DRAG_MIME) || event.dataTransfer.getData("text/plain");
      const dropEdge = resolvePaneDropEdge(event);
      const isSameTabNoOp = draggedTabId === tab.id && terminalTabCount <= 1;
      if (!dropEdge || isSameTabNoOp) {
        event.dataTransfer.dropEffect = "none";
        setIsDragOver(false);
        setDropIndicator(null);
        return;
      }
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      setIsDragOver(true);
      setDropIndicator(dropEdge);
      return;
    }

    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    setIsDragOver(true);
    setDropIndicator(null);
  };

  const handleDragLeave = (event: React.DragEvent) => {
    const related = event.relatedTarget;
    if (related instanceof Node && event.currentTarget.contains(related)) return;
    setIsDragOver(false);
    setDropIndicator(null);
  };

  const handleDrop = (event: React.DragEvent) => {
    const transfer = event.dataTransfer;

    if (!transfer) {
      event.preventDefault();
      const droppedPane = draggedLeafId;
      setIsDragOver(false);
      setDropIndicator(null);
      setDraggedLeafId(null);
      if (droppedPane && droppedPane.tabId === tab.id && droppedPane.leafId !== leafId) {
        onSwapPanes(tab.id, droppedPane.leafId, leafId);
      }
      return;
    }

    const droppedPane = parseDraggedPane(transfer.getData(PANE_DRAG_MIME)) ?? draggedLeafId;
    const droppedTabId = transfer.getData(TAB_DRAG_MIME) || (!droppedPane ? transfer.getData("text/plain") : "");
    const dropEdge = droppedTabId ? resolvePaneDropEdge(event) ?? dropIndicator : null;

    setIsDragOver(false);
    setDropIndicator(null);
    setDraggedLeafId(null);

    if (droppedTabId) {
      if (!dropEdge || (droppedTabId === tab.id && terminalTabCount <= 1)) return;
      event.preventDefault();
      const splitDirection: PaneDirection = dropEdge === "top" || dropEdge === "bottom" ? "vertical" : "horizontal";
      const position = dropEdge === "left" || dropEdge === "top" ? "first" : "second";
      onSplitPane(tab.id, leafId, splitDirection, { sourceTabId: droppedTabId, position });
      return;
    }

    event.preventDefault();
    if (droppedPane && droppedPane.tabId === tab.id && droppedPane.leafId !== leafId) {
      onSwapPanes(tab.id, droppedPane.leafId, leafId);
    }
  };

  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden bg-terminal transition-all ${
        isDragOver && !effectiveDropIndicator ? "ring-2 ring-primary/80 ring-inset" : ""
      }`}
      data-testid="pane-leaf"
      data-leaf-id={leafId}
      data-tab-id={tab.id}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => onFocusPane(tab.id, leafId)}
    >
      <div
        className="absolute inset-x-0 top-0 z-20 h-6"
        data-testid="pane-toolbar-hotspot"
        onMouseEnter={() => setIsHoveredTop(true)}
        onMouseLeave={(event) => {
          const related = event.relatedTarget;
          if (!(related instanceof Element) || !related.closest('[data-testid="pane-toolbar"]')) {
            setIsHoveredTop(false);
          }
        }}
      />

      <div
        draggable
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
        className={`pointer-events-none absolute inset-x-0 top-0 z-30 flex h-6 cursor-grab items-center justify-end border-b border-border/20 bg-background/50 backdrop-blur-md px-2 text-[11px] text-muted-foreground transition-opacity duration-150 active:cursor-grabbing select-none ${
          isHoveredTop ? "pointer-events-auto opacity-100" : "opacity-0"
        }`}
        data-testid="pane-toolbar"
        onMouseEnter={() => setIsHoveredTop(true)}
        onMouseLeave={() => setIsHoveredTop(false)}
      >
        <div className="flex items-center gap-0.5">
          <IconButton
            label="Split pane right"
            size="sm"
            className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
            onClick={(event) => {
              event.stopPropagation();
              onSplitPane(tab.id, leafId, "horizontal");
            }}
          >
            <Columns2 className="size-3" />
          </IconButton>
          <IconButton
            label="Split pane down"
            size="sm"
            className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
            onClick={(event) => {
              event.stopPropagation();
              onSplitPane(tab.id, leafId, "vertical");
            }}
          >
            <Rows2 className="size-3" />
          </IconButton>
          {!isOnlyLeaf ? (
            <IconButton
              label="Close split view"
              size="sm"
              className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
              onClick={(event) => {
                event.stopPropagation();
                onClosePane(tab.id, leafId);
              }}
            >
              <X className="size-3" />
            </IconButton>
          ) : null}
        </div>
      </div>

      {effectiveDropIndicator ? (
        <div
          data-testid="pane-drop-preview"
          data-drop-edge={effectiveDropIndicator}
          aria-hidden="true"
          className={`pointer-events-none absolute z-40 border-2 border-primary bg-primary/20 backdrop-blur-[1px] transition-all duration-100 ${
            effectiveDropIndicator === "left"
              ? "inset-y-0 left-0 w-1/2"
              : effectiveDropIndicator === "right"
                ? "inset-y-0 right-0 w-1/2"
                : effectiveDropIndicator === "top"
                  ? "inset-x-0 top-0 h-1/2"
                  : "inset-x-0 bottom-0 h-1/2"
          }`}
        >
          <span className="pointer-events-none absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm">
            New split
          </span>
        </div>
      ) : null}

      <div className="h-full w-full min-h-0 flex-1 overflow-hidden">
        <TerminalPane
          session={session}
          active={isActive}
          onTitleChange={(title) => onTitleChange(tab.id, title, session.id)}
          onBell={() => onBell?.(session.id, tab.id)}
        />
      </div>
    </div>
  );
}

const MIN_PANE_SIZE_PX = 80;

type PaneResizeDividerProps = {
  direction: PaneDirection;
  ratio: number;
  onRatioChange: (ratio: number) => void;
};

function PaneResizeDivider({ direction, ratio, onRatioChange }: PaneResizeDividerProps) {
  const dividerRef = useRef<HTMLDivElement>(null);
  const draggingRef = useRef(false);
  const isHorizontal = direction === "horizontal";

  const handlePointerDown = (event: React.PointerEvent) => {
    event.preventDefault();
    const parent = dividerRef.current?.parentElement;
    if (!parent) return;

    draggingRef.current = true;
    document.body.style.cursor = isHorizontal ? "col-resize" : "row-resize";
    const parentRect = parent.getBoundingClientRect();

    const handlePointerMove = (pointerEvent: PointerEvent) => {
      if (!draggingRef.current) return;
      const totalSize = isHorizontal ? parentRect.width : parentRect.height;
      if (totalSize <= 0) return;
      if (totalSize <= MIN_PANE_SIZE_PX * 2) {
        onRatioChange(0.5);
        return;
      }
      const position = isHorizontal ? pointerEvent.clientX - parentRect.left : pointerEvent.clientY - parentRect.top;
      const minimumRatio = MIN_PANE_SIZE_PX / totalSize;
      const clampedRatio = Math.max(minimumRatio, Math.min(1 - minimumRatio, position / totalSize));
      onRatioChange(Number(clampedRatio.toFixed(4)));
    };

    const handlePointerUp = () => {
      draggingRef.current = false;
      document.body.style.cursor = "";
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
      window.removeEventListener("pointercancel", handlePointerUp);
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", handlePointerUp);
    window.addEventListener("pointercancel", handlePointerUp);
  };

  return (
    <div
      ref={dividerRef}
      role="separator"
      aria-label="Resize terminal panes"
      aria-orientation={isHorizontal ? "vertical" : "horizontal"}
      aria-valuenow={Math.round(ratio * 100)}
      data-divider-hit-target="true"
      onPointerDown={handlePointerDown}
      className={`no-drag relative z-20 flex shrink-0 touch-none items-center justify-center ${
        isHorizontal ? "w-1.5 cursor-col-resize hover:bg-primary/20" : "h-1.5 cursor-row-resize hover:bg-primary/20"
      }`}
    >
      <span
        data-testid="split-divider-line"
        className={isHorizontal ? "h-full w-px bg-border/80" : "h-px w-full bg-border/80"}
      />
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

import { terminalHostManager, type TerminalInstance } from "../lib/terminalHostManager";
import { useTerminalSettings } from "../lib/terminalSettings";
import type { TerminalSession } from "../lib/types";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
};

function fitMountedTerminal(container: HTMLDivElement, instance: TerminalInstance) {
  if (!container.isConnected || !container.contains(instance.element)) return false;
  const rect = container.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) return false;

  Object.assign(instance.element.style, {
    position: "absolute",
    inset: "0px",
    width: "100%",
    height: "100%",
    minWidth: "0px",
    minHeight: "0px",
    overflow: "hidden",
  });
  instance.fitAddon.fit();
  return true;
}

export function TerminalPane({ session, active, onBell, onTitleChange }: TerminalPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const { settings } = useTerminalSettings();

  useEffect(() => {
    terminalHostManager.applySettings(settings);
  }, [settings]);

  useEffect(() => {
    terminalHostManager.updateSession(session.id, session);
  }, [session]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let cancelled = false;
    let firstFitFrame = 0;
    let secondFitFrame = 0;
    let resizeObserver: ResizeObserver | null = null;

    const cancelScheduledFit = () => {
      if (firstFitFrame) cancelAnimationFrame(firstFitFrame);
      if (secondFitFrame) cancelAnimationFrame(secondFitFrame);
      firstFitFrame = 0;
      secondFitFrame = 0;
    };

    const scheduleStableFit = (instance: TerminalInstance, focus = false) => {
      cancelScheduledFit();
      firstFitFrame = requestAnimationFrame(() => {
        firstFitFrame = 0;
        if (cancelled) return;
        const fitted = fitMountedTerminal(container, instance);
        if (focus && fitted) instance.terminal.focus();
        secondFitFrame = requestAnimationFrame(() => {
          secondFitFrame = 0;
          if (cancelled) return;
          fitMountedTerminal(container, instance);
        });
      });
    };

    void terminalHostManager
      .getOrCreate(session, active, onBell, onTitleChange)
      .then((instance) => {
        if (cancelled) return;
        if (!container.contains(instance.element)) {
          container.replaceChildren(instance.element);
        }

        resizeObserver = new ResizeObserver(() => scheduleStableFit(instance));
        resizeObserver.observe(container);
        scheduleStableFit(instance, active);

        const fontsReady = typeof document !== "undefined" ? document.fonts?.ready : undefined;
        void fontsReady?.then(() => {
          if (!cancelled) scheduleStableFit(instance);
        });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to mount terminal");
      });

    return () => {
      cancelled = true;
      resizeObserver?.disconnect();
      cancelScheduledFit();
    };
  }, [session.id]);

  useEffect(() => {
    const instance = terminalHostManager.getInstance(session.id);
    const container = containerRef.current;
    if (instance) {
      instance.active = active;
      if (active && container) {
        requestAnimationFrame(() => {
          if (fitMountedTerminal(container, instance)) instance.terminal.focus();
        });
      }
    }
  }, [active, session.id]);

  return (
    <div className="relative h-full w-full min-h-0 min-w-0 overflow-hidden bg-terminal">
      <div ref={containerRef} data-testid="terminal-mount" className="relative h-full w-full min-h-0 min-w-0 overflow-hidden" />
      {error ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          {error}
        </div>
      ) : null}
    </div>
  );
}

