  tabs: WorkspaceTab[];
  activeTabId: string;
  onActivate: (id: string) => void;
  onClose: (id: string) => void;
  onCloseOthers?: (id: string) => void;
  onCloseToRight?: (id: string) => void;
  onCloseToLeft?: (id: string) => void;
  onReorderTabs?: (tabId: string, targetIndex: number) => void;
  onTabPointerDragStart?: (tabId: string, point: TabPointerDragPoint) => void;
  onTabPointerDragMove?: (tabId: string, point: TabPointerDragPoint) => void;
  onTabPointerDragEnd?: (tabId: string, point: TabPointerDragPoint) => void;
  onTabPointerDragCancel?: () => void;
  onRenameTab?: (id: string, newLabel: string) => void;
